bool ValidNativeGBuffer(const WXL_VkStageContext&c,const WXL_VkGBuffer&b){return b.structSize>=offsetof(WXL_VkGBuffer,extent)+sizeof(b.extent)&&b.valid&&b.serial==c.serial&&b.layout==VK_IMAGE_LAYOUT_GENERAL&&b.extent.width==c.extent.width&&b.extent.height==c.extent.height&&b.albedoView&&b.normalView&&b.lightView&&b.albedoFormat==VK_FORMAT_R8G8B8A8_UNORM&&b.lightFormat==VK_FORMAT_R8G8B8A8_UNORM&&(b.normalFormat==VK_FORMAT_R16G16B16A16_SNORM||b.normalFormat==VK_FORMAT_R16G16B16A16_SFLOAT||b.normalFormat==VK_FORMAT_R32G32B32A32_SFLOAT);}
bool CommonConstants(const Source::FrameInputs&f,VkExtent2D size,uint32_t scale,Uniforms&u){if(!size.width||!size.height||!f.viewport.Width||!f.viewport.Height||scale<1||scale>4)return false;u={};u.r[0]={float(f.viewport.X),float(f.viewport.Y),float(f.viewport.Width),float(f.viewport.Height)};u.r[1]={float(scale),float(uint64_t(std::max(0.,f.seconds)*60)%1024),1.f/size.width,1.f/size.height};u.r[2]={f.glProjection[0],f.glProjection[5],f.glProjection[8],f.glProjection[9]};float range=f.viewport.MaxZ-f.viewport.MinZ;if(range<=0||std::abs(f.glProjection[11]-1)>1e-5)return false;u.r[3]={f.viewport.MinZ+range*(1+f.glProjection[10])*.5f,range*f.glProjection[14]*.5f,5000,f.viewport.MaxZ>=.99903f?.99903f:f.viewport.MaxZ+.00001f};float inverse[16];if(!Source::Invert4x4(f.cameraRelativeView,inverse))return false;inverse[12]=f.camPos[0];inverse[13]=f.camPos[1];inverse[14]=f.camPos[2];std::memcpy(&u.r[4],inverse,sizeof inverse);auto w=(f.viewport.Width+scale-1)/scale,h=(f.viewport.Height+scale-1)/scale;u.r[8]={float(w),float(h),1.f/w,1.f/h};return true;}
bool NoiseAssets::Init(Gpu&g){if(g_)return g_==&g&&volume_.handle&&cloud_.handle;g_=&g;auto levels=Source::BuildDriftNoise();cloudBytes_=Source::BuildCloudNoise();volumeBytes_.resize(levels.size());for(size_t n=0;n<levels.size();++n){auto&bytes=volumeBytes_[n];bytes.resize(levels[n].argb.size()*4);for(size_t i=0;i<levels[n].argb.size();++i){auto c=levels[n].argb[i];bytes[i*4]=uint8_t(c>>16);bytes[i*4+1]=uint8_t(c>>8);bytes[i*4+2]=uint8_t(c);bytes[i*4+3]=uint8_t(c>>24);}}nextVolume_=nextCloud_=0;return g.CreateVolume(volume_,128,VK_FORMAT_R8G8B8A8_UNORM,uint32_t(levels.size()))&&g.Create(cloud_,256,256,VK_FORMAT_R8_UNORM,uint32_t(cloudBytes_.size()));}
bool NoiseAssets::RecordUploads(){if(!g_)return false;while(nextVolume_<volumeBytes_.size()){auto&v=volumeBytes_[nextVolume_];if(!g_->UploadMip(volume_,nextVolume_,v.data(),v.size()))return false;++nextVolume_;}while(nextCloud_<cloudBytes_.size()){auto&v=cloudBytes_[nextCloud_];if(!g_->UploadMip(cloud_,nextCloud_,v.texels.data(),v.texels.size()))return false;++nextCloud_;}return true;}
bool NoiseAssets::Ready()const{return g_&&volume_.handle&&cloud_.handle&&nextVolume_==volumeBytes_.size()&&nextCloud_==cloudBytes_.size();}
void NoiseAssets::Shutdown(){if(g_){g_->Retire(volume_);g_->Retire(cloud_);}volumeBytes_.clear();cloudBytes_.clear();g_=nullptr;}
