 if(!g_||!map_.handle||!depth.view)return false;auto at=At(basis_,in.camPos,side_);long long sx=at.cell[0]-camera_.cell[0],sy=at.cell[1]-camera_.cell[1];bool forget=!valid_||reset||in.mapId!=mapId_||in.seconds<lastSeconds_||in.seconds-lastSeconds_>.5||std::abs(sx)>=side_||std::abs(sy)>=side_;
 if(forget){double prev[3]={1,0,0};basis_=Source::MakeShaftMemoryFrame(in.toLight,in.camPos,valid_?basis_.u:prev);at=At(basis_,in.camPos,side_);sx=sy=0;fading_=false;if(!g_->Clear(map_,{0,0,0,0})||!g_->Clear(before_,{0,0,0,0}))return false;}
 auto u=common;u.r[9]={float(sx),float(sy),forget?1.f:0.f,std::abs(in.glProjection[5])*in.viewport.Height*.5f};FrameRegisters(u,10,basis_,at,side_);std::array<Texture,16>tex{};tex[0]=g_->Sample(map_);tex[1]=depth;if(!g_->Run(Kernel::MemoryKeep,u,tex,kept_))return false;
 double dot=0,length=0,dist=0;for(int k=0;k<3;++k){dot+=in.toLight[k]*basis_.l[k];length+=double(in.toLight[k])*in.toLight[k];double d=in.camPos[k]-basis_.anchor[k];dist+=d*d;}double cosine=length>0?dot/std::sqrt(length):1;bool align=!forget&&(cosine<std::cos(.2*3.14159265358979/180)||dist>2048.*2048.);
 if(align){if(!g_->Copy(kept_,before_)||!g_->Clear(atomic_,{0,0,0,0}))return false;beforeBasis_=basis_;beforeCamera_=at;auto next=Source::MakeShaftMemoryFrame(in.toLight,in.camPos,basis_.u);auto nextAt=At(next,in.camPos,side_);u=common;u.r[9]={0,0,float(side_)*.5f-2,float(realignments_%4096)};FrameRegisters(u,10,next,nextAt,side_);FrameRegisters(u,14,basis_,at,side_);tex={};tex[0]=g_->Sample(kept_);if(!g_->Run(Kernel::MemoryRealign,u,tex,atomic_))return false;tex={};tex[0]=g_->Sample(atomic_);if(!g_->Run(Kernel::MemoryResolve,u,tex,realigned_))return false;u.r[9]={1.f/side_,0,0,0};tex[0]=g_->Sample(realigned_);if(!g_->Run(Kernel::MemoryFill,u,tex,kept_))return false;double since=in.seconds-lastRealign_;fadeSeconds_=realignments_&&since>0?std::clamp(since*.9,.25,3.):1;lastRealign_=fadeStart_=in.seconds;fading_=true;++realignments_;basis_=next;at=nextAt;}
 tex={};tex[0]=g_->Sample(kept_);if(!g_->Run(Kernel::MemorySeed,common,tex,atomic_))return false;
 static constexpr int order[16][2]={{0,0},{2,2},{2,0},{0,2},{1,1},{3,3},{3,1},{1,3},{1,0},{3,2},{3,0},{1,2},{0,1},{2,3},{2,1},{0,3}};
 u=common;FrameRegisters(u,10,basis_,at,side_);u.r[14]={body.base[0],body.base[1],body.base[2],body.radius};u.r[15]={body.up[0],body.up[1],body.up[2],body.height};tex={};tex[0]=depth;unsigned passes=forget?16:1;for(unsigned n=0;n<passes;++n){unsigned offset=forget?n:frame_%16;u.r[9]={4,float(order[offset][0]),float(order[offset][1]),float(side_)*.5f-2};if(!g_->Run(Kernel::MemoryScatter,u,tex,atomic_,nullptr,{(in.viewport.Width+3)/4,(in.viewport.Height+3)/4}))return false;}tex={};tex[0]=g_->Sample(atomic_);if(!g_->Run(Kernel::MemoryResolve,u,tex,map_))return false;
