bool Composite::Resize(uint32_t w,uint32_t h){if(!g_)return false;g_->Retire(scene_);return g_->Create(scene_,w,h,VK_FORMAT_R8G8B8A8_UNORM);}
bool Composite::Record(const WXL_VkStageContext&ctx,const Uniforms&common,const WXL_VkGBuffer*gb,Texture lamps,Texture fog,Texture halos,VkExtent2D low,CompositeSettings cfg){if(!g_||!ctx.colorImage||!ctx.colorView||!std::isfinite(cfg.lampGain)||cfg.lampGain<0||cfg.lampGain>4||!ctx.depthView||ctx.colorLayout!=VK_IMAGE_LAYOUT_GENERAL||ctx.colorFormat!=VK_FORMAT_R8G8B8A8_UNORM||ctx.extent.width!=scene_.extent.width||ctx.extent.height!=scene_.extent.height)return false;if(!cfg.surfaces&&!cfg.fog&&!cfg.halos)return true;if(cfg.surfaces&&(!gb||!ValidNativeGBuffer(ctx,*gb)||!lamps.view))return false;if((cfg.fog&&!fog.view)||(cfg.halos&&!halos.view)||((cfg.fog||cfg.halos)&&(!low.width||!low.height)))return false;if(!g_->CopyFrame(scene_))return false;
 std::array<Texture,16>t{};t[0]=g_->Sample(scene_);t[1]={ctx.depthView,ctx.depthLayout};t[2]=lamps;if(gb){t[3]={gb->albedoView,VK_IMAGE_LAYOUT_GENERAL};t[4]={gb->lightView,VK_IMAGE_LAYOUT_GENERAL};t[5]={gb->normalView,VK_IMAGE_LAYOUT_GENERAL};}t[6]=fog;t[7]=halos;auto u=common;u.r[9]={cfg.surfaces?1.f:0.f,cfg.fog?1.f:0.f,cfg.halos?1.f:0.f,ctx.swapRB?1.f:0.f};u.r[10]={cfg.lampGain,0,0,0};u.r[11]={float(low.width),float(low.height),common.r[1][0],common.r[1][0]};Target frame;frame.handle=reinterpret_cast<void*>(uintptr_t(1));frame.info.image=ctx.colorImage;frame.info.view=ctx.colorView;frame.extent=ctx.extent;frame.format=ctx.colorFormat;frame.layout=ctx.colorLayout;return g_->Run(Kernel::SceneComposite,u,t,frame);}
void Composite::Shutdown(){if(g_)g_->Retire(scene_);}
